import pytest
from pathlib import Path
from isort.place import _src_path
from unittest.mock import MagicMock

class Config:
    def __init__(self, src_paths, namespace_packages, auto_identify_namespace_packages, supported_extensions):
        self.src_paths = [Path(p) for p in src_paths]
        self.namespace_packages = namespace_packages
        self.auto_identify_namespace_packages = auto_identify_namespace_packages
        self.supported_extensions = supported_extensions

@pytest.fixture
def mock_config():
    return Config(
        src_paths=["src"], 
        namespace_packages=[], 
        auto_identify_namespace_packages=False, 
        supported_extensions=[]
    )

def test_src_path_with_valid_module(mock_config):
    assert _src_path("my_module", mock_config) == ("FIRSTPARTY", "Found in one of the configured src_paths: src.")

def test_src_path_with_namespace(mock_config):
    mock_config.namespace_packages = ["my_namespace"]
    assert _src_path("my_namespace.my_module", mock_config) == ("FIRSTPARTY", "Found in one of the configured src_paths: src.")

def test_src_path_with_empty_src_paths():
    config = Config(
        src_paths=[], 
        namespace_packages=[], 
        auto_identify_namespace_packages=False, 
        supported_extensions=[]
    )
    assert _src_path("my_module", config) is None

def test_src_path_with_non_existent_module(mock_config):
    assert _src_path("non_existent_module", mock_config) is None

def test_src_path_with_only_prefix(mock_config):
    assert _src_path("my_module", mock_config, prefix=("prefix",)) == ("FIRSTPARTY", "Found in one of the configured src_paths: src.")
